const STATE_BY_UF = new Map(STATES.map((state) => [state.uf, state]));

// Routes owned by the separately generated portal (same origin).
export const PORTAL_PREFIXES = ['/precos/', '/postos/', '/consultar/', '/dados/', '/metodologia/', '/curiosidades/', '/fiscalizacao/'];

const PORTAL_LABELS = {
  '/precos/': 'Preços de combustíveis por estado e cidade',
  '/consultar/': 'Consultar postos e preços',
  '/dados/': 'Dados abertos de combustíveis',
  '/metodologia/': 'Metodologia dos dados do abastevo',
  '/curiosidades/': 'Curiosidades dos dados de combustíveis',
  '/fiscalizacao/': 'Fiscalização da ANP: multas publicadas',
};

export function isPortalRoute(route) {
  return PORTAL_PREFIXES.some((prefix) => route === prefix || route.startsWith(prefix));
}

// A portal route the landing may link to: the fixed hubs above or a state hub
// `/precos/{uf}/` with a known lowercase UF code. Deeper portal paths are not
// linked from authored content because the landing cannot verify them.
export function portalRouteLabel(route) {
  if (Object.hasOwn(PORTAL_LABELS, route)) return PORTAL_LABELS[route];
  const state = /^\/precos\/([a-z]{2})\/$/.exec(route);
  if (state && STATE_BY_UF.has(state[1])) return `Preços de combustíveis em ${STATE_BY_UF.get(state[1]).name}`;
  return null;
}

